def main():
    root = Path(__file__).resolve().parent
    for name, rows in CANONICAL_REELS.items():
        cells = [row.split(",") for row in rows.splitlines()]
        assert all(len(row) == 5 and "C" not in row for row in cells)
        (root / (name + ".csv")).write_text(rows + "\n",encoding="utf-8")
        print(f"{name}: {len(cells)} x 5")

if __name__ == "__main__":
    main()
